/**
 * The types `save/lifetime/` exports, in one place — so a neighbouring module finds the shape it
 * needs here instead of declaring its own under a second name.
 */
/* ── file map ─────────────────────────────────────────────────────────────────
 * exports    LifetimeImportEntryFields, LifetimeSaveFieldRow, LifetimeSaveExtract
 * depends    —
 * used by    src/save/lifetime/index, src/save/lifetime/read
 * ─────────────────────────────────────────────── generated by `npm run map` ──
 */

// from read.ts

export interface LifetimeImportEntryFields {
  date: string
  gameStarted: string
  coinsEarned: string
  cashEarned: string
  stonesEarned: string
  keysEarned: string
  cellsEarned?: string
  rerollShardsEarned?: string
  recentCoinsPerHour?: string
  damageDealt: string
  enemiesDestroyed: string
  wavesCompleted: string
  upgradesBought: string
  workshopUpgrades: string
  workshopCoinsSpent: string
  researchCompleted: string
  labCoinsSpent: string
  freeUpgrades: string
  interestEarned: string
  orbKills: string
  deathRayKills: string
  thornDamage: string
  wavesSkipped: string
}

export interface LifetimeSaveFieldRow {
  targetKey: keyof LifetimeImportEntryFields
  saveKey: string | readonly string[]
  /**
   * Spellings this field used to have, tried in order and only when `saveKey` is absent.
   *
   * NOT the same as giving `saveKey` an array: that form SUMS its keys, which is right for a
   * value split across three fields and wrong for a rename, where matching two spellings at once
   * would silently double the number.
   */
  renamedFrom?: readonly string[]
  label: string
  optional?: boolean
}

export interface LifetimeSaveExtract {
  values: Record<string, string>
  warnings: string[]
}
